(() => {
  "use strict";
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const store = {
    get(key, fallback) { try { const v=JSON.parse(localStorage.getItem("hs_"+key)); return v ?? fallback; } catch { return fallback; } },
    set(key, value) { localStorage.setItem("hs_"+key, JSON.stringify(value)); }
  };
  const data = window.HS_DATA;
  let currentUser = store.get("session", null);
  let authMode = "login";
  let activePage = "dashboard";
  let toastTimer;
  const patientNav = [["dashboard","▦","Dashboard"],["emergency","✚","Emergency"],["appointments","＋","Appointments"],["checkups","⌕","Health Checkups"],["donations","♡","Donations"],["eldercare","♧","Elder Care"],["companion","✦","AI Companion"],["profile","◉","My Profile"]];
  const helperNav = [["dashboard","▦","Dashboard"],["requests","◈","Available Requests"],["tasks","✓","My Tasks"],["earnings","₹","Earnings"],["profile","◉","Profile"]];
  const hospitalNav = [["dashboard","▦","Dashboard"],["appointments","＋","Appointments"],["doctors","⚕","Doctors"],["icu","▤","ICU Beds"],["emergency","✚","Ambulance Requests"],["patients","♙","Patients"],["reports","▥","Reports"],["profile","◉","Profile"]];
  const pageNames = {dashboard:"Dashboard",emergency:"Emergency assistance",appointments:"Appointments",checkups:"Health checkups",donations:"Donation centre",eldercare:"Elder care",companion:"AI Health Companion",profile:"My profile",requests:"Available requests",tasks:"My tasks",earnings:"Earnings",doctors:"Doctor management",icu:"ICU bed management",patients:"Patient requests",reports:"Hospital reports"};
  const icons = {emergency:"✚",appointments:"＋",checkups:"⌕",donations:"♡",eldercare:"♧",companion:"✦"};
  function toast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove("show"),2800);}
  function esc(s=""){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
  function id(prefix="HS"){return prefix+"-"+Date.now().toString(36).toUpperCase()+"-"+Math.random().toString(36).slice(2,5).toUpperCase();}
  function getList(key){return store.get(key,[]);}
  function saveList(key,list){store.set(key,list);}
  function dateText(d){return new Date(d).toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"});}
  function money(n){return "₹"+Number(n||0).toLocaleString("en-IN");}
  function roleLabel(role){return role==="hospital"?"Hospital":role==="helper"?"Healthcare helper":"Patient";}
  function userInitial(){return (currentUser?.name||"U").trim().charAt(0).toUpperCase();}
  function openModal(id){$("#"+id).classList.remove("hidden");}
  function closeModals(){$$(".modal-backdrop").forEach(x=>x.classList.add("hidden"));}
  function setAuthMode(mode){authMode=mode;$("#authTitle").textContent=mode==="login"?"Welcome back":"Create your account";$("#authSub").textContent=mode==="login"?"Enter your details to access your workspace.":"A few details to get your care workspace ready.";$("#registerFields").classList.toggle("hidden",mode!=="register");$("#authSubmit").textContent=mode==="login"?"Login →":"Create account →";$$(".auth-tabs button").forEach(b=>b.classList.toggle("active",b.dataset.tab===mode));}
  function login(user){currentUser=user;store.set("session",user);closeModals();$("#publicView").classList.add("hidden");$("#appView").classList.remove("hidden");activePage="dashboard";renderShell();renderPage();toast("Welcome to HealthSphere, "+user.name.split(" ")[0]+"!");}
  function logout(){currentUser=null;store.set("session",null);$("#appView").classList.add("hidden");$("#publicView").classList.remove("hidden");closeModals();toast("You have logged out.");}
  function renderShell(){const nav=currentUser.role==="patient"?patientNav:currentUser.role==="helper"?helperNav:hospitalNav;$("#sideName").textContent=currentUser.name;$("#sideRole").textContent=roleLabel(currentUser.role);$("#sideAvatar").textContent=userInitial();$("#headerAvatar").textContent=userInitial();$("#headerName").textContent=currentUser.name;$("#sideNav").innerHTML=nav.map(([key,ico,label])=>`<button class="side-link ${activePage===key?"active":""}" data-page="${key}"><span>${ico}</span><span>${label}</span></button>`).join("");}
  function go(page){activePage=page;$("#sidebar").classList.remove("open");renderShell();renderPage();window.scrollTo(0,0);}
  function setPageHeader(title){$("#pageTitle").textContent=title||pageNames[activePage]||"Dashboard";$("#pageEyebrow").textContent=currentUser.role.toUpperCase()+" WORKSPACE";}
  function stat(label,value,caption,icon){return `<div class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-caption">${caption}</div></div>`;}
  function statusTag(s){return `<span class="status ${String(s).toLowerCase().replaceAll(" ","-")}">${esc(s)}</span>`;}
  function serviceCard(key,title,desc){return `<button class="dash-service" data-page="${key}"><span class="service-icon ${key==="emergency"?"red":key==="checkups"?"teal":key==="donations"?"orange":key==="eldercare"?"green":"blue"}">${icons[key]}</span><b>${title}</b><small>${desc}</small></button>`;}
  function myItems(key){return getList(key).filter(x=>x.owner===currentUser.email);}
  function renderPatientDashboard(){
    const appointments=myItems("appointments"), emergencies=myItems("emergencies"), checkups=myItems("checkups"), elder=myItems("eldercare");
    return `<div class="welcome-row"><div><h2>Hello, ${esc(currentUser.name.split(" ")[0])} 👋</h2><p>Here's an overview of your healthcare activity today.</p></div><button class="btn btn-primary" data-page="appointments">＋ Book appointment</button></div>
    <div class="stats-grid">${stat("UPCOMING APPOINTMENTS",appointments.filter(x=>x.status!=="Cancelled").length,"Your scheduled visits","＋")}${stat("HEALTH CHECKUPS",checkups.length,"Packages booked","⌕")}${stat("CARE REQUESTS",emergencies.length+elder.length,"Emergency & elder care","♡")}${stat("PROFILE STATUS","Active","Demo account","✓")}</div>
    <div class="panel" style="margin-bottom:18px"><div class="panel-title"><h3>Explore health services</h3><small>Choose a service to get started</small></div><div class="service-dashboard-grid">${serviceCard("emergency","Emergency","Request urgent assistance")}${serviceCard("appointments","Regular checkups","Book a doctor visit")}${serviceCard("checkups","Health checkups","Screening packages")}${serviceCard("donations","Donations","Blood & organ awareness")}${serviceCard("eldercare","Elder care","Arrange daily support")}</div></div>
    <div class="dashboard-grid"><div class="panel"><div class="panel-title"><h3>Upcoming appointments</h3><button class="btn-quiet" data-page="appointments">View all</button></div>${appointments.length?appointments.slice(-3).reverse().map(x=>`<div class="list-row"><div class="list-icon">＋</div><div class="list-main"><b>${esc(x.doctor)} · ${esc(x.speciality)}</b><small>${dateText(x.date)} · ${esc(x.time)} · ${esc(x.hospital)}</small></div>${statusTag(x.status)}</div>`).join(""):`<div class="empty-state">◷<b>No appointments yet</b>Book a doctor visit when you're ready.</div>`}</div>
    <div class="panel"><div class="panel-title"><h3>AI Health Companion</h3><small>DEMO ASSISTANT</small></div><div class="list-row"><div class="list-icon">✦</div><div class="list-main"><b>Need general health information?</b><small>Ask questions or get help finding a service.</small></div></div><button class="btn btn-primary full-btn" data-page="companion">Open companion →</button><p style="font-size:9px">Not for diagnosis, prescriptions or emergencies.</p></div></div>`;
  }
  function renderHelperDashboard(){
    const tasks=myItems("tasks"), open=getList("requests").filter(x=>x.status==="Requested");
    const earned=tasks.filter(x=>x.status==="Completed").reduce((a,x)=>a+Number(x.fee||0),0);
    return `<div class="welcome-row"><div><h2>Welcome, ${esc(currentUser.name.split(" ")[0])} 👋</h2><p>Find meaningful care tasks and manage your work.</p></div><span class="verification">● Demo verification pending</span></div>
    <div class="stats-grid">${stat("AVAILABLE REQUESTS",open.length,"Requests to review","◈")}${stat("ACTIVE TASKS",tasks.filter(x=>x.status!=="Completed").length,"Accepted assignments","✓")}${stat("COMPLETED TASKS",tasks.filter(x=>x.status==="Completed").length,"Approved demo tasks","♧")}${stat("DEMO EARNINGS",money(earned),"Completed task value","₹")}</div>
    <div class="dashboard-grid"><div class="panel"><div class="panel-title"><h3>New care requests</h3><button class="btn-quiet" data-page="requests">View requests</button></div>${open.slice(0,4).map(x=>requestRow(x,true)).join("")||`<div class="empty-state">✦<b>No new requests</b>New patient requests will appear here.</div>`}</div><div class="panel"><div class="panel-title"><h3>Your work at a glance</h3></div><p style="font-size:11px">Keep your availability and profile details up to date. Patient details are shown only for accepted demo tasks.</p><button class="btn btn-primary full-btn" data-page="tasks">Manage my tasks →</button></div></div>`;
  }
  function renderHospitalDashboard(){
    const appts=getList("appointments"), mine=appts.filter(x=>x.hospitalOwner===currentUser.email);
    const emergencies=getList("emergencies").filter(x=>x.hospital===currentUser.organisation||!x.hospital);
    return `<div class="welcome-row"><div><h2>${esc(currentUser.organisation||currentUser.name)} 👋</h2><p>Hospital operations overview and incoming patient requests.</p></div><span class="verification">● Demo verification pending</span></div>
    <div class="stats-grid">${stat("APPOINTMENT REQUESTS",mine.filter(x=>x.status==="Requested").length,"Awaiting response","＋")}${stat("TOTAL APPOINTMENTS",mine.length,"All booking requests","▦")}${stat("ICU BEDS AVAILABLE",currentUser.icu??3,"Demo availability","▤")}${stat("AMBULANCE REQUESTS",emergencies.length,"Requests in the demo","✚")}</div>
    <div class="dashboard-grid"><div class="panel"><div class="panel-title"><h3>Appointment requests</h3><button class="btn-quiet" data-page="appointments">Manage all</button></div>${mine.slice(-4).reverse().map(x=>`<div class="list-row"><div class="list-icon">＋</div><div class="list-main"><b>${esc(x.patient)} · ${esc(x.speciality)}</b><small>${dateText(x.date)} · ${esc(x.time)}</small></div>${statusTag(x.status)}</div>`).join("")||`<div class="empty-state">▦<b>No requests yet</b>New appointment bookings will appear here.</div>`}</div><div class="panel"><div class="panel-title"><h3>Quick management</h3></div><div class="list-row"><div class="list-icon">⚕</div><div class="list-main"><b>Doctors & availability</b><small>Manage your doctor directory.</small></div><button class="btn-quiet" data-page="doctors">Open</button></div><div class="list-row"><div class="list-icon">▤</div><div class="list-main"><b>ICU beds</b><small>Update available beds.</small></div><button class="btn-quiet" data-page="icu">Open</button></div><div class="list-row"><div class="list-icon">✚</div><div class="list-main"><b>Emergency requests</b><small>Coordinate urgent requests.</small></div><button class="btn-quiet" data-page="emergency">Open</button></div></div></div>`;
  }
  function requestRow(x,helper=false){return `<div class="list-row"><div class="list-icon">${x.type==="Emergency assistance"?"✚":"♧"}</div><div class="list-main"><b>${esc(x.type)} · ${esc(x.patient||"Patient")}</b><small>${esc(x.location||x.hospital||"Location shared after acceptance")} · ${money(x.fee||250)}</small></div>${helper?`<button class="btn-quiet" data-action="accept-request" data-id="${x.id}">Review</button>`:statusTag(x.status)}</div>`;}
  function renderDashboard(){return currentUser.role==="patient"?renderPatientDashboard():currentUser.role==="helper"?renderHelperDashboard():renderHospitalDashboard();}
  function appointmentPage(){
    if(currentUser.role==="hospital") return hospitalAppointments();
    const mine=myItems("appointments");
    return `<div class="welcome-row"><div><h2>Doctor appointments</h2><p>Search specialists and book a convenient slot.</p></div><button class="btn btn-primary" data-action="book-appointment">＋ New appointment</button></div><div class="panel"><div class="search-row"><input id="doctorSearch" placeholder="Search doctors, specialities or hospitals…" /><select id="specialityFilter" style="max-width:180px"><option value="">All specialities</option>${[...new Set(data.doctors.map(d=>d.speciality))].map(s=>`<option>${s}</option>`).join("")}</select></div><div id="doctorResults">${doctorCards(data.doctors)}</div></div><div class="panel" style="margin-top:16px"><div class="panel-title"><h3>My bookings</h3><small>${mine.length} total</small></div>${mine.length?mine.slice().reverse().map(x=>`<div class="list-row"><div class="list-icon">＋</div><div class="list-main"><b>${esc(x.doctor)} · ${esc(x.speciality)}</b><small>${dateText(x.date)} · ${esc(x.time)} · ${esc(x.hospital)}</small></div>${statusTag(x.status)}${x.status!=="Cancelled"?`<button class="btn-quiet btn-danger" data-action="cancel-booking" data-id="${x.id}">Cancel</button>`:""}</div>`).join(""):`<div class="empty-state">No appointments booked yet.</div>`}</div>`;
  }
  function doctorCards(list){return list.map(d=>`<div class="list-row"><div class="list-icon">⚕</div><div class="list-main"><b>${esc(d.name)}</b><small>${esc(d.speciality)} · ${esc(d.hospital)} · ${money(d.fee)}</small></div><button class="btn-quiet" data-action="book-doctor" data-id="${d.id}">Book slot</button></div>`).join("")||`<div class="empty-state">No matching doctors found.</div>`;}
  function hospitalAppointments(){const mine=getList("appointments").filter(x=>x.hospitalOwner===currentUser.email);return `<div class="welcome-row"><div><h2>Appointment management</h2><p>Review and respond to patient appointment requests.</p></div></div><div class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>PATIENT</th><th>DOCTOR / SPECIALITY</th><th>DATE & TIME</th><th>AMOUNT</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${mine.map(x=>`<tr><td><strong>${esc(x.patient)}</strong><br>${esc(x.owner)}</td><td>${esc(x.doctor)}<br>${esc(x.speciality)}</td><td>${dateText(x.date)}<br>${esc(x.time)}</td><td>${money(x.amount)}</td><td>${statusTag(x.status)}</td><td><div class="action-group">${x.status==="Requested"?`<button class="btn-quiet" data-action="appointment-status" data-id="${x.id}" data-status="Accepted">Accept</button><button class="btn-quiet btn-danger" data-action="appointment-status" data-id="${x.id}" data-status="Rejected">Reject</button>`:"—"}</div></td></tr>`).join("")||`<tr><td colspan="6">No appointment requests yet.</td></tr>`}</tbody></table></div></div>`;}
  function emergencyPage(){
    const mine=currentUser.role==="patient"?myItems("emergencies"):getList("emergencies");
    if(currentUser.role==="hospital")return `<div class="welcome-row"><div><h2>Ambulance coordination</h2><p>Review emergency requests in this local demo.</p></div></div><div class="panel">${mine.map(x=>`<div class="list-row"><div class="list-icon">✚</div><div class="list-main"><b>${esc(x.patient)} · ${esc(x.kind)}</b><small>${esc(x.location)} · ${dateText(x.created)}</small></div>${statusTag(x.status)}<button class="btn-quiet" data-action="emergency-status" data-id="${x.id}">Update</button></div>`).join("")||`<div class="empty-state">No emergency requests.</div>`}</div>`;
    return `<div class="notice"><b>Important:</b> HealthSphere is a demonstration only. It does not dispatch a real ambulance or provide live tracking. For an emergency in India, call <b>112</b> or your local emergency service immediately. Do not wait for this demo.</div><div class="dashboard-grid"><div class="panel"><div class="panel-title"><h3>Request emergency assistance</h3><small>DEMO REQUEST</small></div><form id="emergencyForm"><div class="field"><label>Emergency type</label><select name="kind"><option>Medical emergency</option><option>Accident emergency</option><option>Ambulance required</option><option>ICU bed enquiry</option></select></div><div class="field"><label>Patient / contact name</label><input name="patient" required value="${esc(currentUser.name)}"/></div><div class="field"><label>Contact number</label><input name="phone" required inputmode="tel" placeholder="Mobile number"/></div><div class="field"><label>Pickup / current location</label><input name="location" id="emergencyLocation" required placeholder="Enter address or use location"/></div><button class="btn-quiet" type="button" data-action="get-location">◎ Use my current location</button><div class="field" style="margin-top:15px"><label>Additional details</label><textarea name="details" placeholder="Share only information needed for coordination"></textarea></div><button class="btn btn-primary" type="submit">Submit demo request →</button></form></div><div class="panel"><div class="panel-title"><h3>Nearby hospitals</h3><small>SAMPLE DIRECTORY</small></div>${data.hospitals.map(h=>`<div class="list-row"><div class="list-icon">⌂</div><div class="list-main"><b>${esc(h.name)}</b><small>${esc(h.location)} · ICU beds (sample): ${h.icu}</small></div><a class="btn-quiet" href="tel:${h.phone.replaceAll(" ","")}" title="Call sample hospital">Call</a></div>`).join("")}<div class="map-placeholder"><div><b>⌖</b>Map preview unavailable offline<br><small>Location is only accessed after permission.</small></div></div></div></div><div class="panel" style="margin-top:16px"><div class="panel-title"><h3>My emergency requests</h3></div>${mine.length?mine.slice().reverse().map(x=>`<div class="list-row"><div class="list-icon">✚</div><div class="list-main"><b>${esc(x.kind)} · ${esc(x.id)}</b><small>${esc(x.location)} · ${dateText(x.created)}</small><div class="progress-steps">${["Requested","Accepted","Assigned","On the Way","Completed"].map((s,i)=>`<span class="${["Requested","Accepted","Assigned","On the Way","Completed"].indexOf(x.status)>=i?"done":""}"></span>`).join("")}</div></div>${statusTag(x.status)}</div>`).join(""):`<div class="empty-state">No emergency requests submitted.</div>`}</div>`;
  }
  function checkupsPage(){const mine=myItems("checkups");return `<div class="welcome-row"><div><h2>Health checkup packages</h2><p>Choose a screening package and collection preference.</p></div></div><div class="notice">Package names and prices are sample demo data. Confirm tests, preparation and pricing with the laboratory before booking.</div><div class="service-grid">${data.packages.map(p=>`<article class="panel"><div class="service-icon teal">⌕</div><h3 style="font-size:15px">${esc(p.name)}</h3><p style="font-size:11px;min-height:45px">${esc(p.detail)}</p><h3 style="font-size:21px;color:var(--teal)">${money(p.price)}</h3><button class="btn btn-primary full-btn" data-action="book-checkup" data-id="${p.id}">Book package</button></article>`).join("")}</div><div class="panel" style="margin-top:17px"><div class="panel-title"><h3>My checkup bookings</h3></div>${mine.length?mine.slice().reverse().map(x=>`<div class="list-row"><div class="list-icon">⌕</div><div class="list-main"><b>${esc(x.package)}</b><small>${esc(x.collection)} · ${dateText(x.date)}</small></div>${statusTag(x.status)}<b>${money(x.amount)}</b></div>`).join(""):`<div class="empty-state">No health checkups booked.</div>`}</div>`;}
  function donationsPage(){const registrations=myItems("donations");return `<div class="welcome-row"><div><h2>Give the gift of life</h2><p>Learn about donation and register your interest.</p></div></div><div class="notice">Donation registration here is an expression of interest only. It does not establish medical eligibility or guarantee donation. Organ donation requires official medical and legal procedures and coordination with authorised organisations.</div><div class="three-grid"><div class="panel"><div class="service-icon red">♥</div><h3>Blood donation</h3><p style="font-size:11px">Blood donation is voluntary. Eligibility depends on age, health, weight and screening by the blood bank.</p><button class="btn btn-primary full-btn" data-action="donation-form" data-kind="Blood">Register interest</button></div><div class="panel"><div class="service-icon orange">♡</div><h3>Organ donation</h3><p style="font-size:11px">Learn about pledging and discuss your wishes with family. Follow official NOTTO / authorised processes.</p><button class="btn btn-primary full-btn" data-action="donation-form" data-kind="Organ">Register interest</button></div><div class="panel"><div class="service-icon teal">✦</div><h3>Donation awareness</h3><p style="font-size:11px">Understand donation pathways and share verified awareness resources with your community.</p><a class="text-link" href="https://notto.mohfw.gov.in/" target="_blank" rel="noopener">Official NOTTO website ↗</a></div></div><div class="panel" style="margin-top:17px"><div class="panel-title"><h3>My registrations</h3></div>${registrations.length?registrations.map(x=>`<div class="list-row"><div class="list-icon">♡</div><div class="list-main"><b>${esc(x.kind)} donation interest</b><small>${esc(x.bloodGroup||"")} · ${dateText(x.created)}</small></div>${statusTag(x.status)}</div>`).join(""):`<div class="empty-state">No donation interests registered.</div>`}</div>`;}
  function elderPage(){const mine=myItems("eldercare");return `<div class="welcome-row"><div><h2>Elder care assistance</h2><p>Arrange practical support for an older family member.</p></div><button class="btn btn-primary" data-action="elder-form">＋ Request assistance</button></div><div class="three-grid"><div class="panel"><div class="service-icon green">♧</div><h3>Daily care</h3><p style="font-size:11px">Companionship and non-medical daily assistance.</p></div><div class="panel"><div class="service-icon blue">＋</div><h3>Hospital visit</h3><p style="font-size:11px">Help coordinating transport and accompanying a visit.</p></div><div class="panel"><div class="service-icon orange">⌕</div><h3>Medicine pickup</h3><p style="font-size:11px">Assistance purchasing prescribed medicines. Helpers do not prescribe.</p></div></div><div class="panel" style="margin-top:17px"><div class="panel-title"><h3>Available demo helpers</h3></div>${data.helpers.map(h=>`<div class="list-row"><div class="list-icon">♧</div><div class="list-main"><b>${h.name}</b><small>${h.skill} · ★ ${h.rating}</small></div><span class="status">Available</span></div>`).join("")}</div><div class="panel" style="margin-top:17px"><div class="panel-title"><h3>My elder care requests</h3></div>${mine.length?mine.slice().reverse().map(x=>`<div class="list-row"><div class="list-icon">♧</div><div class="list-main"><b>${esc(x.service)} · ${esc(x.patient)}</b><small>${dateText(x.date)} · ${esc(x.location)}</small></div>${statusTag(x.status)}</div>`).join(""):`<div class="empty-state">No elder care requests yet.</div>`}</div>`;}
  function companionPage(){return `<div class="notice"><b>Demo assistant:</b> This companion provides general information only. It cannot diagnose, prescribe, interpret emergencies or replace a qualified clinician. For an emergency in India, call 112.</div><div class="panel"><div class="panel-title"><h3>✦ HealthSphere Companion</h3><small><span class="online-dot"></span> DEMO MODE</small></div><div class="chat-window"><div class="chat-messages" id="chatMessages"><div class="message bot">Hello ${esc(currentUser.name.split(" ")[0])}! I'm the HealthSphere demo companion. I can explain general wellness topics or help you find a platform service. What would you like to know?</div></div><div class="quick-prompts"><button data-action="chat-prompt" data-text="How can I book a doctor appointment?">Book an appointment</button><button data-action="chat-prompt" data-text="What checkup packages are available?">Checkup packages</button><button data-action="chat-prompt" data-text="How can I support an elderly family member?">Elder care</button><button data-action="chat-prompt" data-text="I have an emergency">Emergency help</button></div><form class="chat-send" id="chatForm"><input name="message" id="chatInput" required placeholder="Ask a general health or service question…"/><button class="btn btn-primary" type="submit">Send ➤</button></form></div></div>`;}
  function profilePage(){return `<div class="profile-grid"><div class="panel profile-card"><div class="profile-big">${userInitial()}</div><h3>${esc(currentUser.name)}</h3><p>${esc(currentUser.email)}</p><span class="verification">DEMO ${roleLabel(currentUser.role).toUpperCase()}</span><p style="margin-top:18px">This local demo stores your profile in this browser only.</p></div><div class="panel"><div class="panel-title"><h3>Edit profile</h3></div><form id="profileForm"><div class="form-grid"><div class="field"><label>Full name</label><input name="name" required value="${esc(currentUser.name)}"/></div><div class="field"><label>Mobile number</label><input name="mobile" value="${esc(currentUser.mobile||"")}"/></div><div class="field"><label>Email address</label><input value="${esc(currentUser.email)}" disabled/></div><div class="field"><label>Role</label><input value="${roleLabel(currentUser.role)}" disabled/></div>${currentUser.role==="hospital"?`<div class="field full"><label>Hospital / organisation</label><input name="organisation" value="${esc(currentUser.organisation||"")}"/></div>`:""}</div><button class="btn btn-primary">Save changes</button></form><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><div class="panel-title"><h3>Privacy & demo settings</h3></div><p style="font-size:11px">Location is requested only when you select “Use my current location”. No real payment or ambulance dispatch is connected.</p><button class="btn-quiet btn-danger" data-action="clear-demo">Clear local demo data</button></div></div>`;}
  function requestsPage(){const requests=getList("requests").filter(x=>x.status==="Requested");return `<div class="welcome-row"><div><h2>Available care requests</h2><p>Review a request before accepting. Patient details are shared after acceptance in this demo.</p></div></div><div class="panel">${requests.map(x=>`<div class="list-row"><div class="list-icon">${x.type==="Emergency assistance"?"✚":"♧"}</div><div class="list-main"><b>${esc(x.type)}</b><small>${esc(x.location||"Location provided after acceptance")} · ${dateText(x.created)} · Demo fee ${money(x.fee)}</small></div><button class="btn-quiet" data-action="accept-request" data-id="${x.id}">Review & accept</button></div>`).join("")||`<div class="empty-state">◈<b>No available requests</b>Check again later for new assistance requests.</div>`}</div>`;}
  function tasksPage(){const tasks=myItems("tasks");return `<div class="welcome-row"><div><h2>My assigned tasks</h2><p>Update the progress of accepted care assignments.</p></div></div><div class="panel">${tasks.map(x=>`<div class="list-row"><div class="list-icon">✓</div><div class="list-main"><b>${esc(x.type)}</b><small>${esc(x.patient)} · ${esc(x.location)} · ${dateText(x.created)}</small></div>${statusTag(x.status)}${x.status!=="Completed"?`<button class="btn-quiet" data-action="task-next" data-id="${x.id}">Update status</button>`:""}</div>`).join("")||`<div class="empty-state">No tasks accepted yet.</div>`}</div>`;}
  function earningsPage(){const tasks=myItems("tasks"),completed=tasks.filter(x=>x.status==="Completed");return `<div class="stats-grid">${stat("COMPLETED TASKS",completed.length,"Approved demo tasks","✓")}${stat("TOTAL DEMO EARNINGS",money(completed.reduce((s,x)=>s+Number(x.fee||0),0)),"Not a real payout","₹")}${stat("PENDING TASKS",tasks.filter(x=>x.status!=="Completed").length,"In progress","◷")}${stat("PAYMENT STATUS","Demo","No real transfer","↗")}</div><div class="notice">Earnings shown are illustrative task values only. No money is collected or paid by this demo platform.</div><div class="panel"><div class="panel-title"><h3>Task payment history</h3></div>${completed.map(x=>`<div class="list-row"><div class="list-icon">₹</div><div class="list-main"><b>${esc(x.type)}</b><small>${dateText(x.created)} · ${esc(x.id)}</small></div><span class="status completed">Demo credited</span><b>${money(x.fee)}</b></div>`).join("")||`<div class="empty-state">Completed task earnings will appear here.</div>`}</div>`;}
  function doctorsPage(){if(currentUser.role!=="hospital")return `<div class="panel">This section is for hospital accounts.</div>`;const mine=store.get("hospitalDoctors_"+currentUser.email,[]);return `<div class="welcome-row"><div><h2>Doctor directory</h2><p>Manage doctors and their appointment availability.</p></div><button class="btn btn-primary" data-action="add-doctor">＋ Add doctor</button></div><div class="panel">${[...data.doctors,...mine].map(d=>`<div class="list-row"><div class="list-icon">⚕</div><div class="list-main"><b>${esc(d.name)}</b><small>${esc(d.speciality)} · ${esc(d.hospital)} · Fee ${money(d.fee)}</small></div><span class="status">Available</span></div>`).join("")}</div>`;}
  function icuPage(){return `<div class="welcome-row"><div><h2>ICU bed availability</h2><p>Update sample availability for your hospital profile.</p></div></div><div class="panel"><div class="notice">This is a local demonstration. Availability is not connected to a hospital admission system. Always confirm directly with the hospital.</div><div class="field"><label>Available ICU beds (demo)</label><input id="icuCount" type="number" min="0" max="100" value="${Number(currentUser.icu??3)}"/></div><button class="btn btn-primary" data-action="save-icu">Save availability</button></div>`;}
  function patientsPage(){const list=getList("appointments").filter(x=>x.hospitalOwner===currentUser.email);return `<div class="panel"><div class="panel-title"><h3>Patient booking requests</h3><small>Only demo bookings linked to this hospital</small></div>${list.map(x=>`<div class="list-row"><div class="list-icon">♙</div><div class="list-main"><b>${esc(x.patient)}</b><small>${esc(x.speciality)} · ${dateText(x.date)} · ${esc(x.time)} · ${esc(x.owner)}</small></div>${statusTag(x.status)}</div>`).join("")||`<div class="empty-state">No patient requests yet.</div>`}</div>`;}
  function reportsPage(){const mine=getList("appointments").filter(x=>x.hospitalOwner===currentUser.email);return `<div class="stats-grid">${stat("TOTAL BOOKINGS",mine.length,"Demo records","▦")}${stat("ACCEPTED",mine.filter(x=>x.status==="Accepted").length,"Confirmed in demo","✓")}${stat("PENDING",mine.filter(x=>x.status==="Requested").length,"Awaiting review","◷")}${stat("DEMO BOOKING VALUE",money(mine.filter(x=>x.status==="Accepted").reduce((s,x)=>s+x.amount,0)),"Not actual revenue","₹")}</div><div class="panel"><div class="panel-title"><h3>Booking activity</h3></div><p style="font-size:11px">Summary is calculated from local demo appointment records. No real patient system or financial account is connected.</p><div class="list-row"><div class="list-main"><b>Accepted appointments</b><small>${mine.filter(x=>x.status==="Accepted").length} bookings</small></div><span class="status completed">Accepted</span></div><div class="list-row"><div class="list-main"><b>Pending appointments</b><small>${mine.filter(x=>x.status==="Requested").length} bookings</small></div><span class="status pending">Requested</span></div></div>`;}
  function renderPage(){setPageHeader();let html="";switch(activePage){case"dashboard":html=renderDashboard();break;case"emergency":html=emergencyPage();break;case"appointments":html=appointmentPage();break;case"checkups":html=checkupsPage();break;case"donations":html=donationsPage();break;case"eldercare":html=elderPage();break;case"companion":html=companionPage();break;case"profile":html=profilePage();break;case"requests":html=requestsPage();break;case"tasks":html=tasksPage();break;case"earnings":html=earningsPage();break;case"doctors":html=doctorsPage();break;case"icu":html=icuPage();break;case"patients":html=patientsPage();break;case"reports":html=reportsPage();break;default:html=renderDashboard();}$("#pageContent").innerHTML=html;}
  function showGeneric(title,body){$("#genericModalContent").innerHTML=`<h2>${title}</h2>${body}`;openModal("genericModal");}
  function paymentDialog({title,description,amount,onConfirm,extra=""}){showGeneric(title,`<p>${description}</p>${extra}<div class="receipt"><div class="receipt-line"><span>Service amount</span><b>${money(amount)}</b></div><div class="receipt-line"><span>Platform fee</span><b>${money(0)}</b></div><div class="receipt-line total"><span>Total</span><b>${money(amount)}</b></div></div><div class="notice" style="margin-top:14px">DEMO PAYMENT · No real money will be charged. Do not enter a UPI PIN or card details.</div><label>Payment method<select id="paymentMethod"><option>UPI (simulated)</option><option>Pay at hospital (demo)</option></select></label><div class="modal-actions"><button class="btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="confirm-payment">Confirm demo booking</button></div>`);window.pendingPayment={amount,onConfirm};}
  function bookDoctor(d){showGeneric("Book an appointment",`<p>${esc(d.name)} · ${esc(d.speciality)}</p><form id="doctorBookingForm"><input type="hidden" name="doctorId" value="${d.id}"/><div class="field"><label>Hospital</label><input value="${esc(d.hospital)}" disabled/></div><div class="form-grid"><div class="field"><label>Date</label><input name="date" type="date" min="${new Date().toISOString().slice(0,10)}" required/></div><div class="field"><label>Available time</label><select name="time">${d.slots.map(s=>`<option>${s}</option>`).join("")}</select></div></div><div class="field"><label>Reason for visit (optional)</label><input name="reason" placeholder="Brief reason"/></div><div class="modal-actions"><button type="button" class="btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary">Continue · ${money(d.fee)}</button></div></form>`);}
  function submitDoctorBooking(form){const fd=new FormData(form),d=data.doctors.find(x=>x.id===fd.get("doctorId"));const date=fd.get("date");if(!date){toast("Please select an appointment date.");return;}paymentDialog({title:"Confirm appointment",description:`Appointment with ${d.name} at ${d.hospital}.`,amount:d.fee,onConfirm:()=>{const record={id:id("APT"),owner:currentUser.email,patient:currentUser.name,doctor:d.name,speciality:d.speciality,hospital:d.hospital,hospitalOwner:store.get("hospitalOwner_"+d.hospital,""),date,time:fd.get("time"),reason:fd.get("reason"),amount:d.fee,status:"Requested",created:new Date().toISOString()};saveList("appointments",[...getList("appointments"),record]);saveList("payments",[...getList("payments"),{id:id("PAY"),owner:currentUser.email,amount:d.fee,method:$("#paymentMethod")?.value||"UPI simulated",status:"Demo confirmed",created:new Date().toISOString(),reference:record.id}]);closeModals();go("appointments");toast("Demo appointment request saved.");}});}
  function acceptRequest(requestId){const req=getList("requests"),r=req.find(x=>x.id===requestId);if(!r)return;showGeneric("Review care request",`<div class="notice">Accepting this request shares the contact and task details included in this local demo record.</div><div class="receipt"><div class="receipt-line"><span>Service</span><b>${esc(r.type)}</b></div><div class="receipt-line"><span>Patient</span><b>${esc(r.patient)}</b></div><div class="receipt-line"><span>Location</span><b>${esc(r.location)}</b></div><div class="receipt-line"><span>Demo task value</span><b>${money(r.fee)}</b></div></div><div class="modal-actions"><button class="btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="confirm-accept" data-id="${r.id}">Accept request</button></div>`);}
  function chatReply(q){const s=q.toLowerCase();if(/emergency|accident|chest pain|can't breathe|unconscious|bleeding/.test(s))return "If someone may be in immediate danger, call India's emergency number 112 now (or your local emergency number). Do not wait for this chatbot. I cannot assess emergencies. If safe, seek urgent professional care.";if(/appointment|doctor|book/.test(s))return "You can open Appointments from the patient dashboard, choose a doctor and available demo slot, select a date, then confirm the simulated booking. The request is saved in this browser.";if(/checkup|test|package|blood test/.test(s))return "Open Health Checkups to see sample packages such as Basic Wellness, Complete Body, Diabetes Screening and Heart Health. Confirm test details and preparation with a qualified laboratory.";if(/elder|old|parent|grand/.test(s))return "Open Elder Care to request daily assistance, hospital visit support, appointment assistance or medicine pickup. Helpers cannot prescribe or change medication.";if(/medicine|tablet|drug/.test(s))return "For medication questions, follow the prescription and speak to a qualified doctor or pharmacist. The demo helper service can assist with pickup, but cannot recommend or prescribe medicines.";if(/donat|blood|organ/.test(s))return "Visit Donations for general information and to register interest. Registration is not medical eligibility or a guarantee. Organ donation requires official procedures; see the authorised NOTTO website.";return "I can share general wellness information and explain HealthSphere services. I can't diagnose, prescribe or replace a clinician. You could ask me how to book an appointment, find a checkup package or request elder care.";}
  function appendChat(text,isUser=false){const box=$("#chatMessages");if(!box)return;const el=document.createElement("div");el.className="message "+(isUser?"user":"bot");el.textContent=text;box.appendChild(el);box.scrollTop=box.scrollHeight;}
  document.addEventListener("click",e=>{
    const page=e.target.closest("[data-page]");if(page){e.preventDefault();go(page.dataset.page);return;}
    const b=e.target.closest("[data-action]");if(!b)return;const a=b.dataset.action;
    if(a==="open-auth"){setAuthMode(b.dataset.mode||"login");openModal("authModal");}
    else if(a==="close-modal")closeModals();
    else if(a==="auth-tab")setAuthMode(b.dataset.tab);
    else if(a==="logout")logout();
    else if(a==="toggle-password"){const f=$("#passwordField");f.type=f.type==="password"?"text":"password";b.textContent=f.type==="password"?"Show":"Hide";}
    else if(a==="sample-login"){const role=b.dataset.role;login({name:role==="patient"?"Aarav Patient":role==="helper"?"Arun Helper":"GreenLife Hospital",email:role+"@demo.healthsphere",role,organisation:role==="hospital"?"GreenLife Multispeciality Hospital":undefined,icu:4});}
    else if(a==="forgot"){showGeneric("Password help",`<p>This offline demo does not send password reset emails. If you created a demo account, register again with a new email or clear local demo data from your profile.</p><div class="modal-actions"><button class="btn btn-primary" data-action="close-modal">Okay</button></div>`);}
    else if(a==="book-appointment"){go("appointments");}
    else if(a==="book-doctor"){const d=data.doctors.find(x=>x.id===b.dataset.id);if(d)bookDoctor(d);}
    else if(a==="cancel-booking"){const list=getList("appointments");const x=list.find(x=>x.id===b.dataset.id&&x.owner===currentUser.email);if(x){x.status="Cancelled";saveList("appointments",list);renderPage();toast("Appointment cancelled in demo.");}}
    else if(a==="appointment-status"){const list=getList("appointments"),x=list.find(x=>x.id===b.dataset.id);if(x){x.status=b.dataset.status;saveList("appointments",list);renderPage();toast("Appointment "+x.status.toLowerCase()+".");}}
    else if(a==="book-checkup"){const p=data.packages.find(x=>x.id===b.dataset.id);showGeneric("Book health checkup",`<p>${esc(p.name)} · ${money(p.price)}</p><form id="checkupForm"><div class="field"><label>Preferred date</label><input type="date" name="date" min="${new Date().toISOString().slice(0,10)}" required/></div><div class="field"><label>Collection method</label><select name="collection"><option>Home collection</option><option>Visit laboratory</option></select></div><div class="field"><label>Area / address</label><input name="location" placeholder="Area or address" required/></div><div class="modal-actions"><button type="button" class="btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary">Continue · ${money(p.price)}</button></div></form>`);window.pendingPackage=p;}
    else if(a==="donation-form"){const kind=b.dataset.kind;showGeneric(`${kind} donation interest`, `<p>Register your interest. This is not an official donor registration or eligibility confirmation.</p><form id="donationForm"><input type="hidden" name="kind" value="${kind}"/><div class="field"><label>Full name</label><input name="name" required value="${esc(currentUser.name)}"/></div><div class="field"><label>Contact number</label><input name="phone" required value="${esc(currentUser.mobile||"")}"/></div>${kind==="Blood"?`<div class="field"><label>Blood group (if known)</label><select name="bloodGroup"><option>Not sure</option>${["A+","A-","B+","B-","AB+","AB-","O+","O-"].map(x=>`<option>${x}</option>`).join("")}</select></div>`:""}<div class="modal-actions"><button type="button" class="btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary">Register interest</button></div></form>`);}
    else if(a==="elder-form"){showGeneric("Request elder care",`<p>Request practical, non-medical assistance for a family member.</p><form id="elderForm"><div class="field"><label>Service needed</label><select name="service"><option>Daily care assistance</option><option>Hospital visit assistance</option><option>Doctor appointment assistance</option><option>Medicine purchasing assistance</option><option>Transportation coordination</option></select></div><div class="field"><label>Elderly patient's name</label><input name="patient" required placeholder="Patient name"/></div><div class="field"><label>Contact number</label><input name="phone" required inputmode="tel" placeholder="Contact number"/></div><div class="field"><label>Location</label><input name="location" required placeholder="Address / area"/></div><div class="field"><label>Preferred date</label><input name="date" type="date" min="${new Date().toISOString().slice(0,10)}" required/></div><div class="modal-actions"><button type="button" class="btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary">Submit request</button></div></form>`);}
    else if(a==="get-location"){const input=$("#emergencyLocation");if(!navigator.geolocation){toast("Location is not supported by this browser.");return;}b.disabled=true;b.textContent="Finding location…";navigator.geolocation.getCurrentPosition(pos=>{input.value=`${pos.coords.latitude.toFixed(5)}, ${pos.coords.longitude.toFixed(5)} (GPS)`;b.disabled=false;b.textContent="◎ Use my current location";toast("Location added. It will be saved only when you submit.");},err=>{b.disabled=false;b.textContent="◎ Use my current location";toast(err.code===1?"Location permission denied. Enter the address manually.":"Unable to retrieve location. Enter it manually.");},{enableHighAccuracy:false,timeout:10000});}
    else if(a==="accept-request")acceptRequest(b.dataset.id);
    else if(a==="confirm-accept"){const r=getList("requests"),x=r.find(x=>x.id===b.dataset.id);if(x){x.status="Accepted";saveList("requests",r);const task={...x,owner:currentUser.email,status:"Accepted",created:new Date().toISOString()};saveList("tasks",[...getList("tasks"),task]);closeModals();go("tasks");toast("Request accepted. Task added.");}}
    else if(a==="task-next"){const list=getList("tasks"),x=list.find(x=>x.id===b.dataset.id&&x.owner===currentUser.email);if(x){const states=["Accepted","Assigned","On the Way","Completed"];x.status=states[Math.min(states.indexOf(x.status)+1,3)];saveList("tasks",list);renderPage();toast("Task status updated: "+x.status);}}
    else if(a==="chat-prompt"){const text=b.dataset.text;appendChat(text,true);appendChat(chatReply(text));}
    else if(a==="notifications"){showGeneric("Notifications",`<p>You are all caught up. New demo booking and task updates will appear in your workspace when available.</p><div class="modal-actions"><button class="btn btn-primary" data-action="close-modal">Close</button></div>`);}
    else if(a==="clear-demo"){showGeneric("Clear local demo data?",`<p>This removes locally stored demo accounts, bookings, requests and payments from this browser. This cannot be undone.</p><div class="modal-actions"><button class="btn-quiet" data-action="close-modal">Keep data</button><button class="btn btn-primary" data-action="confirm-clear">Clear data</button></div>`);}
    else if(a==="confirm-clear"){Object.keys(localStorage).filter(k=>k.startsWith("hs_")).forEach(k=>localStorage.removeItem(k));closeModals();logout();}
    else if(a==="save-icu"){const n=Number($("#icuCount").value);if(!Number.isInteger(n)||n<0){toast("Enter a valid bed count.");return;}currentUser.icu=n;store.set("session",currentUser);toast("Demo ICU availability updated.");}
    else if(a==="add-doctor"){showGeneric("Add doctor",`<form id="addDoctorForm"><div class="field"><label>Doctor name</label><input name="name" required/></div><div class="field"><label>Speciality</label><input name="speciality" required/></div><div class="field"><label>Consultation fee (₹)</label><input name="fee" type="number" min="0" required/></div><div class="modal-actions"><button type="button" class="btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary">Add doctor</button></div></form>`);}
  });
  document.addEventListener("submit",e=>{
    const f=e.target;
    if(f.id==="authForm"){e.preventDefault();const fd=new FormData(f),email=String(fd.get("email")).trim().toLowerCase(),password=String(fd.get("password"));if(authMode==="register"){const name=String(fd.get("name")||"").trim(),mobile=String(fd.get("mobile")||"").trim(),role=fd.get("role");if(!name||!/^\d{10}$/.test(mobile)){toast("Enter your name and a valid 10-digit mobile number.");return;}if(password!==fd.get("confirm")){toast("Passwords do not match.");return;}if(password.length<6){toast("Password must be at least 6 characters.");return;}const users=store.get("users",[]);if(users.some(u=>u.email===email)){toast("An account with this email already exists.");return;}const user={name,email,password,mobile,role,organisation:fd.get("organisation")||""};users.push(user);store.set("users",users);if(role==="hospital"&&user.organisation)store.set("hospitalOwner_"+user.organisation,email);login(user);}else{const user=store.get("users",[]).find(u=>u.email===email&&u.password===password);if(!user){toast("Account not found or password incorrect. Try a demo account.");return;}login(user);} }
    else if(f.id==="emergencyForm"){e.preventDefault();const fd=new FormData(f);const x={id:id("EMG"),owner:currentUser.email,patient:fd.get("patient"),phone:fd.get("phone"),kind:fd.get("kind"),location:fd.get("location"),details:fd.get("details"),status:"Requested",created:new Date().toISOString(),fee:350};saveList("emergencies",[...getList("emergencies"),x]);saveList("requests",[...getList("requests"),{...x,type:"Emergency assistance"}]);renderPage();toast("Demo request saved. No ambulance has been dispatched.");}
    else if(f.id==="doctorBookingForm"){e.preventDefault();submitDoctorBooking(f);}
    else if(f.id==="checkupForm"){e.preventDefault();const fd=new FormData(f),p=window.pendingPackage;paymentDialog({title:"Confirm health checkup",description:`${p.name} · ${fd.get("collection")} at ${fd.get("location")}.`,amount:p.price,onConfirm:()=>{const x={id:id("CHK"),owner:currentUser.email,package:p.name,collection:fd.get("collection"),location:fd.get("location"),date:fd.get("date"),amount:p.price,status:"Requested",created:new Date().toISOString()};saveList("checkups",[...getList("checkups"),x]);saveList("payments",[...getList("payments"),{id:id("PAY"),owner:currentUser.email,amount:p.price,status:"Demo confirmed",created:new Date().toISOString(),reference:x.id}]);closeModals();go("checkups");toast("Demo checkup booking saved.");}});}
    else if(f.id==="donationForm"){e.preventDefault();const fd=new FormData(f),x={id:id("DON"),owner:currentUser.email,kind:fd.get("kind"),name:fd.get("name"),phone:fd.get("phone"),bloodGroup:fd.get("bloodGroup")||"",status:"Interest registered",created:new Date().toISOString()};saveList("donations",[...getList("donations"),x]);closeModals();renderPage();toast("Donation interest saved in this browser.");}
    else if(f.id==="elderForm"){e.preventDefault();const fd=new FormData(f),x={id:id("ELD"),owner:currentUser.email,service:fd.get("service"),type:"Elder care assistance",patient:fd.get("patient"),phone:fd.get("phone"),location:fd.get("location"),date:fd.get("date"),status:"Requested",created:new Date().toISOString(),fee:250};saveList("eldercare",[...getList("eldercare"),x]);saveList("requests",[...getList("requests"),{...x,type:x.service}]);closeModals();go("eldercare");toast("Elder care request saved in demo.");}
    else if(f.id==="chatForm"){e.preventDefault();const text=String(new FormData(f).get("message")).trim();if(text){appendChat(text,true);appendChat(chatReply(text));$("#chatInput").value="";}}
    else if(f.id==="profileForm"){e.preventDefault();const fd=new FormData(f);currentUser={...currentUser,name:fd.get("name"),mobile:fd.get("mobile"),organisation:fd.get("organisation")||currentUser.organisation};store.set("session",currentUser);const users=store.get("users",[]).map(u=>u.email===currentUser.email?{...u,...currentUser}:u);store.set("users",users);renderShell();renderPage();toast("Profile updated.");}
    else if(f.id==="addDoctorForm"){e.preventDefault();const fd=new FormData(f),list=store.get("hospitalDoctors_"+currentUser.email,[]);list.push({id:id("DOC"),name:fd.get("name"),speciality:fd.get("speciality"),fee:Number(fd.get("fee")),hospital:currentUser.organisation,slots:["10:00 AM","02:00 PM"]});store.set("hospitalDoctors_"+currentUser.email,list);closeModals();renderPage();toast("Doctor added to local directory.");}
  });
  document.addEventListener("click",e=>{const c=e.target.closest("[data-action='confirm-payment']");if(c&&window.pendingPayment){const fn=window.pendingPayment.onConfirm;window.pendingPayment=null;fn();}});
  $("#doctorSearch")?.addEventListener("input",filterDoctors);$("#specialityFilter")?.addEventListener("change",filterDoctors);
  function filterDoctors(){const q=($("#doctorSearch")?.value||"").toLowerCase(),sp=$("#specialityFilter")?.value||"";$("#doctorResults").innerHTML=doctorCards(data.doctors.filter(d=>(!sp||d.speciality===sp)&&[d.name,d.speciality,d.hospital].join(" ").toLowerCase().includes(q)));}
  $("#mobileMenu").addEventListener("click",()=>$("#mainNav").classList.toggle("open"));
  $("#sideToggle").addEventListener("click",()=>$("#sidebar").classList.toggle("open"));
  if(currentUser){$("#publicView").classList.add("hidden");$("#appView").classList.remove("hidden");renderShell();renderPage();}
})();